<?php require __DIR__.'/../bootstrap.php';$token=preg_replace('/[^A-Za-z0-9_-]/','',(string)($_GET['token']??''));$s=db()->prepare("SELECT * FROM file_objects WHERE public_token=? AND status='clean'");$s->execute([$token]);$f=$s->fetch();if(!$f){http_response_code(404);exit('File not found.');}$url=file_public_url($token);?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>QR — <?=e($f['original_name'])?></title><style>body{font-family:system-ui;background:#f6f8fc}.box{max-width:700px;margin:30px auto;background:#fff;padding:24px;border-radius:18px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.btn{padding:10px 14px;border:0;border-radius:10px;background:#5b4bdb;color:#fff;font-weight:700}@media(max-width:700px){.grid{grid-template-columns:1fr}}.box{width:min(700px,calc(100% - 28px));box-sizing:border-box}.grid>*{min-width:0}input{max-width:100%;box-sizing:border-box}@media(max-width:700px){.box{margin:16px auto;padding:18px}.btn{margin:3px 0}}
</style></head><body><main class="box"><h1>File QR Code</h1><p><?=e($f['original_name'])?></p><div class="grid"><div><label>Foreground <input type="color" id="fg" value="#111827"></label><br><label>Background <input type="color" id="bg" value="#ffffff"></label><br><label>Resolution <input id="size" type="number" min="128" max="2048" value="768"></label><br><label>Center logo URL <input id="logo" style="width:100%"></label><br><button class="btn" id="gen">Generate</button> <button class="btn" id="png">PNG</button> <button class="btn" id="svg">SVG</button></div><div id="box" style="display:grid;place-items:center"></div></div></main><script src="https://cdnjs.cloudflare.com/ajax/libs/qrcode-generator/1.4.4/qrcode.min.js"></script><script>const U=<?=json_encode($url)?>;function gen(){const size=Math.min(2048,Math.max(128,+document.getElementById('size').value||768)),qr=qrcode(0,'H');qr.addData(U);qr.make();const svg=qr.createSvgTag({cellSize:Math.max(2,Math.floor(size/qr.getModuleCount())),margin:4,scalable:true});document.getElementById('box').innerHTML=svg;const s=document.querySelector('#box svg');s.setAttribute('width',size);s.setAttribute('height',size);const fg=document.getElementById('fg').value;document.querySelectorAll('#box rect').forEach(r=>{if(r.getAttribute('fill')&&r.getAttribute('fill')!=='none')r.setAttribute('fill',fg)});const logo=document.getElementById('logo').value.trim();if(logo){const ns='http://www.w3.org/2000/svg',i=document.createElementNS(ns,'image');i.setAttribute('href',logo);i.setAttribute('x',size*.38);i.setAttribute('y',size*.38);i.setAttribute('width',size*.24);i.setAttribute('height',size*.24);i.setAttribute('preserveAspectRatio','xMidYMid slice');s.appendChild(i);}}document.getElementById('gen').onclick=gen;document.getElementById('svg').onclick=()=>{const x=new XMLSerializer().serializeToString(document.querySelector('#box svg'));const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([x],{type:'image/svg+xml'}));a.download='pocketcat-file-qr.svg';a.click()};document.getElementById('png').onclick=()=>{const x=new XMLSerializer().serializeToString(document.querySelector('#box svg')),i=new Image();i.onload=()=>{const c=document.createElement('canvas'),n=+document.getElementById('size').value||768;c.width=c.height=n;c.getContext('2d').drawImage(i,0,0,n,n);const a=document.createElement('a');a.href=c.toDataURL('image/png');a.download='pocketcat-file-qr.png';a.click()};i.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(x)};gen();</script></body></html>
